DO $$ DECLARE r jsonb; BEGIN r:=public.get_hotel_historical_room_board('2001-02-01'); IF jsonb_array_length(r->'unavailable')<>0 OR (SELECT sum(jsonb_array_length(room->'segments')) FROM jsonb_array_elements(r->'rooms') room)<>2 THEN RAISE EXCEPTION 'stationary Shared actual use: %',r; END IF; END $$;
DO $$ DECLARE r jsonb; BEGIN
 r:=public.get_hotel_historical_room_board('2001-02-03');
